<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue"; import { useRoute, useRouter } from "vue-router"; import { getWorkflowConfig, listRepairs, type Repair } from "../api"; import { repairStatusLabel } from "../status-labels"; import { chatUnreadByRepair } from "../../chat/notifications";
const route = useRoute(); const router = useRouter(); const repairs = ref<Repair[]>([]); const statuses = ref<string[]>([]); const loading = ref(true); const error = ref(""); const query = ref(String(route.query.q ?? "")); const status = ref(String(route.query.estado ?? "")); let debounce: number | undefined;
const filtered = computed(() => repairs.value.filter((repair) => `${repair.brand} ${repair.model} ${repair.deviceType}`.toLowerCase().includes(query.value.toLowerCase()) && (!status.value || repair.status === status.value)));
async function load() { loading.value = true; try { const [orders, config] = await Promise.all([listRepairs(), getWorkflowConfig()]); repairs.value = orders; statuses.value = config.statuses; } catch (reason) { error.value = (reason as Error).message; } finally { loading.value = false; } } watch([query, status], () => { window.clearTimeout(debounce); debounce = window.setTimeout(() => void router.replace({ query: { q: query.value || undefined, estado: status.value || undefined } }), 300); }); onMounted(load);
</script>
<template><section><header><div><p class="eyebrow">Taller</p><h1>Reparaciones <span class="count">{{ filtered.length }}</span></h1></div><RouterLink class="button-link" :to="{ name: 'repairs.create' }">Nueva reparacion</RouterLink></header><div class="filter-bar"><input v-model="query" placeholder="Buscar equipo, marca o modelo" /><select v-model="status"><option value="">Todos los estados</option><option v-for="item in statuses" :key="item" :value="item">{{ repairStatusLabel(item) }}</option></select></div><p v-if="error" class="feedback error">{{ error }}</p><div class="customer-list"><div v-if="loading" v-for="item in 5" :key="item" class="skeleton-row" /><p v-else-if="!filtered.length" class="empty">No hay reparaciones que coincidan.</p><RouterLink v-else v-for="repair in filtered" :key="repair.id" class="customer-row" :to="{ name: 'repairs.detail.general', params: { id: repair.id } }"><strong>{{ repair.brand }} {{ repair.model }}</strong><span>{{ repair.deviceType }}</span><span>{{ repair.reportedIssue }}</span><span class="status-pill">{{ repairStatusLabel(repair.status) }}</span><span v-if="chatUnreadByRepair[repair.id]" class="chat-badge">{{ chatUnreadByRepair[repair.id] }}</span></RouterLink></div></section></template>
